def is_samepatterns(colors, patterns):
    """
    Check whether the `colors` list follows the sequence given in the
    `patterns` list, i.e., there exists a one-to-one (bijective) mapping
    between elements of `colors` and elements of `patterns` such that
    corresponding positions match.

    Examples:
        is_samepatterns(["red","green","green"], ["a", "b", "b"]) == True
        is_samepatterns(["red","green","green"], ["a", "b", "a"]) == False
        is_samepatterns(["red","red","red"],     ["a", "b", "b"]) == False
    """
    # Sequences must have the same length to follow the same pattern
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for c, p in zip(colors, patterns):
        # Check/record mapping from color to pattern
        if c in color_to_pattern:
            if color_to_pattern[c] != p:
                return False
        else:
            color_to_pattern[c] = p

        # Check/record mapping from pattern to color (ensures bijection)
        if p in pattern_to_color:
            if pattern_to_color[p] != c:
                return False
        else:
            pattern_to_color[p] = c

    return True


if __name__ == "__main__":
    assert is_samepatterns(["red", "green", "green"], ["a", "b", "b"]) == True
    assert is_samepatterns(["red", "green", "green"], ["a", "b", "a"]) == False
    assert is_samepatterns(["red", "red", "red"], ["a", "b", "b"]) == False
    assert is_samepatterns(["red", "green"], ["a", "b"]) == True
    print("All tests passed!")
